\begin{columns}[c,onlytextwidth]
  \column{0.57\textwidth}
\small
\begin{itemize}\setlength{\itemsep}{4pt}
  \item En el circuito en serie, la resonancia ocurre cuando $X_L = X_C$.
  \item Con $L = 10\ \text{mH}$, $C = 0.1\ \mu\text{F}$ y $V_S = 2\ \text{V}$: $f_r = 5.03\ \text{kHz}$ y $X_L = 316\ \Omega$.
\end{itemize}
  \column{0.4\textwidth}
\begin{cardO}{Error frecuente}
\footnotesize Creer que en la resonancia la corriente es infinita porque la reactancia total es cero.
\end{cardO}
\end{columns}

